draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    ctx.moveTo(W / 2 + Math.sin(t + i) * 50, H / 2);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 50 + Math.cos(t + i) * 20, H / 2 + Math.sin(t + i) * 10);
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 30, H / 2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
